#!/usr/bin/env python3
import sys, os, csv, json, sqlite3, re, gzip, bz2, lzma
from datetime import datetime
from collections import OrderedDict

HELP_TEXT = """trdsql - Execute SQL queries on CSV, LTSV, JSON, YAML and TBLN.

Usage
	trdsql [OPTIONS] [SQL(SELECT...)]

Options:
  -A string           analyze the file but only suggest SQL.
