  -t string           read table name from the specified file.
  -version            display version information.

Input Formats:
  -icsv               CSV format for input.
  -ig                 guess format from extension. (default "true")
  -ijson              JSON format for input.
  -iltsv              LTSV format for input.
  -itbln              TBLN format for input.
  -itext              text format for input.
  -iwidth             width specification format for input.
  -iyaml              YAML format for input.

Input options:
  -id string          field delimiter for input. (default ",")
  -ih                 the first line is interpreted as column names(CSV only).
  -ijq string         jq expression string for input(JSON/JSONL only).
  -ilr int            limited number of rows to read. (default 0)
  -inull value        value(string) to convert to null on input.
  -inum               add row number column.
  -ir int             number of rows to preread. (default 1)
  -is int             skip header row. (default 0)

Output Formats:
  -oat                ASCII Table format for output.
  -ocsv               CSV format for output.
  -ojson              JSON format for output.
  -ojsonl             JSON lines format for output.
  -oltsv              LTSV format for output.
  -omd                Markdown format for output.
  -oraw               Raw format for output.
  -otbln              TBLN format for output.
  -ovf                Vertical format for output.
  -oyaml              YAML format for output.

Output options:
  -oaq                enclose all fields in quotes for output.
  -ocrlf              use CRLF for output. End each output line with '\r\n' instead of '\n'.
  -od string          field delimiter for output. (default ",")
  -oh                 output column name as header.
  -onowrap            do not wrap long lines(at/md only).
  -onull value        value(string) to convert from null on output.
  -oq string          quote character for output. (default "\"")
  -out string         output file name.
  -out-without-guess  output without guessing (when using -out).
  -oz string          output compression format. [ gz | bz2 | zstd | lz4 | xz ]

Examples:
  $ trdsql "SELECT c1,c2 FROM test.csv"
  $ trdsql -oltsv "SELECT c1,c2 FROM test.json::.items"
  $ cat test.csv | trdsql -icsv -oltsv "SELECT c1,c2 FROM -"
"""

STRING_FLAGS = {"A","a","config","db","driver","dsn","q","t","id","ijq","inull","od","onull","oq","out","oz"}
INT_FLAGS = {"ilr","ir","is"}
BOOL_FLAGS = {"dblist","debug","help","version","icsv","ig","ijson","iltsv","itbln","itext","iwidth","iyaml","ih","inum","oat","ocsv","ojson","ojsonl","oltsv","omd","oraw","otbln","ovf","oyaml","oaq","ocrlf","oh","onowrap","out-without-guess"}
OUTPUT_FLAGS = ["oat","ocsv","ojson","ojsonl","oltsv","omd","oraw","otbln","ovf","oyaml"]
INPUT_FLAGS = ["icsv","ijson","iltsv","itbln","itext","iwidth","iyaml"]

class TrdError(Exception):
    def __init__(self, msg, prefix="export"):
        super().__init__(msg)
        self.msg = msg
        self.prefix = prefix

class Options:
    def __init__(self):
        self.vals = {k: False for k in BOOL_FLAGS}
        self.vals.update({k: "" for k in STRING_FLAGS})
        self.vals.update({k: 0 for k in INT_FLAGS})
        self.vals["ig"] = True
        self.vals["id"] = ","
        self.vals["od"] = ","
        self.vals["oq"] = '"'
        self.vals["ir"] = 1
        self.onull_set = False
        self.explicit_output = False
        self.args = []
    def __getitem__(self, k):
        return self.vals[k]
    def __setitem__(self, k, v):
        self.vals[k] = v


def print_usage_and_exit(msg=None):
    if msg:
        sys.stderr.write(msg + "\n")
    sys.stderr.write(HELP_TEXT)
    sys.exit(2)


def parse_bool(s):
    sl = str(s).lower()
    if sl in ("1","t","true","y","yes","on"):
        return True
    if sl in ("0","f","false","n","no","off"):
        return False
    raise ValueError("parse error")


def parse_args(argv):
    opt = Options()
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--":
            opt.args.extend(argv[i+1:]); break
        if not a.startswith("-") or a == "-":
            opt.args.extend(argv[i:]); break
        raw = a[2:] if a.startswith("--") else a[1:]
        if raw == "":
            opt.args.extend(argv[i:]); break
        if "=" in raw:
            name, val = raw.split("=",1)
            has_eq = True
        else:
            name, val = raw, None
            has_eq = False
        if name not in STRING_FLAGS and name not in INT_FLAGS and name not in BOOL_FLAGS:
            dash = "--" if a.startswith("--") else "-"
            print_usage_and_exit(f"flag provided but not defined: {dash}{name}")
        if name in BOOL_FLAGS:
            if has_eq:
                try: b = parse_bool(val)
                except Exception:
                    print_usage_and_exit(f"invalid boolean value \"{val}\" for -{name}")
                opt[name] = b
            else:
                opt[name] = True
            if name in OUTPUT_FLAGS and opt[name]:
                opt.explicit_output = True
            i += 1
            continue
        # string or int consumes an argument if not =
        if not has_eq:
            if i+1 >= len(argv):
                print_usage_and_exit(f"flag needs an argument: -{name}")
            val = argv[i+1]
            i += 2
        else:
            i += 1
        if name in INT_FLAGS:
            try:
                opt[name] = int(val)
            except Exception:
                print_usage_and_exit(f"invalid value \"{val}\" for flag -{name}: parse error")
        else:
            opt[name] = val
            if name == "onull": opt.onull_set = True
    return opt


def nowstamp():
    return datetime.now().strftime("%Y/%m/%d %H:%M:%S")


def log_error(prefix, msg, query=None):
    if query is not None:
        sys.stderr.write(f"{nowstamp()} {prefix}: {msg} [{query}]\n")
    else:
        sys.stderr.write(f"{nowstamp()} {prefix}: {msg}\n")


def read_text_file(path):
    if path == "-":
        return sys.stdin.read()
    try:
        with open(path, "r", encoding="utf-8", newline="") as f:
            return f.read()
    except UnicodeDecodeError:
        with open(path, "r", encoding="utf-8", errors="replace", newline="") as f:
            return f.read()


def delimiter_from(s):
    if s == "\\t": return "\t"
    if s == "tab": return "\t"
    return s[0] if s else ","


def guess_format(path, opt):
    for flag, fmt in [("icsv","csv"),("ijson","json"),("iltsv","ltsv"),("itbln","tbln"),("itext","text"),("iwidth","width"),("iyaml","yaml")]:
        if opt[flag]: return fmt
    if not opt["ig"]:
        return "csv"
    lower = (path or "").lower()
    # selectors are appended after ::
    if "::" in lower: lower = lower.split("::",1)[0]
    if lower.endswith(".ltsv"):
        return "ltsv"
    if lower.endswith(".json") or lower.endswith(".jsonl") or lower.endswith(".ndjson"):
        return "json"
    if lower.endswith(".yaml") or lower.endswith(".yml"):
        return "yaml"
    if lower.endswith(".tbln"):
        return "tbln"
    if lower.endswith(".txt"):
        return "csv"
    return "csv"


def convert_inull(v, opt):
    if v is None: return None
    if opt["inull"] != "" and str(v) == opt["inull"]:
        return None
    return v


def scalar_to_text(v, compact=True):
    if v is None:
        return None
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (int,float)):
        return str(v)
    if isinstance(v, (dict,list)):
        if compact:
            return json.dumps(v, ensure_ascii=False, separators=(",",":"))
        return json.dumps(v, ensure_ascii=False)
    return str(v)


def unique_or_error(cols):
    seen = set()
    for c in cols:
        if c in seen:
            raise TrdError(f"duplicate column name: {c}", "import")
        seen.add(c)


def parse_csv_rows(text, path, opt):
    delim = delimiter_from(opt["id"])
    if path.lower().endswith(".tsv") and not opt["icsv"] and opt["id"] == "," and opt["ig"]:
        delim = "\t"
    reader = csv.reader(text.splitlines(), delimiter=delim)
    allrows = list(reader)
    if opt["is"]:
        allrows = allrows[max(0,opt["is"]):]
    cols = []
    data = []
    if opt["ih"]:
        if allrows:
            hdr = allrows[0]
            for idx, h in enumerate(hdr, 1):
                cols.append(h if h != "" else f"c{idx}")
            data = allrows[1:]
        else:
            cols = []
            data = []
        unique_or_error(cols)
    else:
        preread = max(1, opt["ir"] or 1)
        width = 0
        for r in allrows[:preread]:
            width = max(width, len(r))
        cols = [f"c{i}" for i in range(1,width+1)]
        data = allrows
    if opt["ilr"]:
        data = data[:opt["ilr"]]
    outrows = []
    for idx, r in enumerate(data, 1):
        rr = [(r[i] if i < len(r) else "") for i in range(len(cols))]
        rr = [convert_inull(x, opt) for x in rr]
        if opt["inum"]:
            rr = [str(idx)] + rr
        outrows.append(rr)
    if opt["inum"]:
        cols = ["num"] + cols
    return cols, ["TEXT"]*len(cols), outrows


def parse_ltsv_line(line):
    d = OrderedDict()
    if line.endswith("\r"):
        line = line[:-1]
    if line == "":
        return d
    for part in line.split("\t"):
        if ":" in part:
            k,v = part.split(":",1)
            d[k] = v
    return d


def parse_ltsv_rows(text, opt):
    lines = text.splitlines()
    if opt["is"]:
        lines = lines[max(0,opt["is"]):]
    dicts = [parse_ltsv_line(line) for line in lines]
    preread = max(1, opt["ir"] or 1)
    cols = []
    seen = set()
    for d in dicts[:preread]:
        for k in d.keys():
            if k not in seen:
                seen.add(k); cols.append(k)
    data_dicts = dicts
    if opt["ilr"]:
        data_dicts = data_dicts[:opt["ilr"]]
    rows = []
    for idx, d in enumerate(data_dicts,1):
        row = [convert_inull(d.get(c,""), opt) for c in cols]
        if opt["inum"]:
            row = [str(idx)] + row
        rows.append(row)
    if opt["inum"]:
        cols = ["num"] + cols
    return cols, ["TEXT"]*len(cols), rows


def apply_selector(data, selector):
    if not selector:
        return data
    sel = selector.strip()
    if sel.startswith("::"):
        sel = sel[2:]
    # trdsql uses gojq-like expressions; implement common .a.b, [n], [] forms.
    if sel.startswith("."):
        sel = sel[1:]
    else:
        raise TrdError(f"function not defined: {sel.split('.',1)[0]}/0 gojq:({selector}) ", "import")
    cur = data
    parts = []
    i=0
    buf=""
    while i < len(sel):
        ch = sel[i]
        if ch == '.':
            if buf:
                parts.append(buf); buf=""
            i += 1; continue
        buf += ch; i += 1
    if buf: parts.append(buf)
    for p in parts:
        # handle name[], name[0], [0]
        m = re.match(r"^([^\[]*)(?:\[(.*?)\])?$", p)
        name = p; idx = None; iterate = False
        if m:
            name = m.group(1)
            b = m.group(2)
            if b is not None:
                if b == "": iterate = True
                else:
                    try: idx = int(b)
                    except: idx = None
        if name:
            if isinstance(cur, dict):
                cur = cur.get(name)
            elif isinstance(cur, list):
                cur = [x.get(name) if isinstance(x,dict) else None for x in cur]
            else:
                cur = None
        if iterate:
            # list already represents rows; if nested lists, flatten one level
            if isinstance(cur, list):
                flat=[]
                for x in cur:
                    if isinstance(x, list): flat.extend(x)
                    else: flat.append(x)
                cur = flat
        elif idx is not None:
            if isinstance(cur, list):
                cur = cur[idx] if 0 <= idx < len(cur) else None
            else:
                cur = None
    return cur


def json_records_from_data(data, compact=True):
    if isinstance(data, list):
        return data
    return [data]


def parse_json_rows(text, path, selector, opt):
    s = text.strip()
    data = None
    if not s:
        data = []
    else:
        try:
            data = json.loads(s, object_pairs_hook=OrderedDict)
        except Exception:
            # JSON lines fallback
            arr=[]
            for line in text.splitlines():
                if line.strip():
                    arr.append(json.loads(line, object_pairs_hook=OrderedDict))
            data = arr
    jq = opt["ijq"] or selector
    if jq:
        data = apply_selector(data, jq)
    recs = json_records_from_data(data)
    if opt["is"]:
        recs = recs[max(0,opt["is"]):]
    if opt["ilr"]:
        recs = recs[:opt["ilr"]]
    cols=[]; seen=set()
    scalar_mode = False
    for rec in recs:
        if isinstance(rec, dict):
            for k in rec.keys():
                if k not in seen:
                    seen.add(k); cols.append(k)
        else:
            scalar_mode = True
            if "c1" not in seen:
                seen.add("c1"); cols.append("c1")
    rows=[]
    for idx, rec in enumerate(recs,1):
        if isinstance(rec, dict):
            row=[convert_inull(scalar_to_text(rec.get(c), compact=True), opt) for c in cols]
        else:
            row=[convert_inull(scalar_to_text(rec, compact=True), opt)]
            row += [None]*(len(cols)-1)
        if opt["inum"]:
            row=[str(idx)]+row
        rows.append(row)
    if opt["inum"]:
        cols=["num"]+cols
    return cols, ["TEXT"]*len(cols), rows


def parse_simple_scalar(s):
    s = s.strip()
    if s == "" or s == "null" or s == "~":
        return None if s in ("null","~") else ""
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        return s[1:-1]
    if s.startswith("{") and s.endswith("}"):
        return parse_inline_map(s)
    if s.startswith("[") and s.endswith("]"):
        # try JSON-ish, then comma split
        try: return json.loads(s)
        except Exception:
            inner=s[1:-1].strip()
            if not inner: return []
            return [parse_simple_scalar(x) for x in split_top_commas(inner)]
    if s == "true": return True
    if s == "false": return False
    # keep numbers as numbers internally; insertion converts to strings for yaml input
    if re.match(r"^-?\d+$", s):
        try: return int(s)
        except: pass
    if re.match(r"^-?\d+\.\d+", s):
        try: return float(s)
        except: pass
    return s


def split_top_commas(s):
    parts=[]; buf=""; depth=0; quote=None; i=0
    while i < len(s):
        ch=s[i]
        if quote:
            buf += ch
            if ch == quote: quote=None
        else:
            if ch in "'\"": quote=ch; buf+=ch
            elif ch in "[({": depth+=1; buf+=ch
            elif ch in "])}": depth-=1; buf+=ch
            elif ch == ',' and depth==0:
                parts.append(buf.strip()); buf=""
            else: buf+=ch
        i+=1
    if buf or s.endswith(','): parts.append(buf.strip())
    return parts


def parse_inline_map(s):
    inner=s.strip()[1:-1].strip()
    od=OrderedDict()
    if not inner: return od
    for part in split_top_commas(inner):
        if ':' in part:
            k,v=part.split(':',1)
            k=k.strip().strip('"\'')
            od[k]=parse_simple_scalar(v)
    return od


def parse_yaml_text(text):
    # A deliberately small YAML subset for user-facing examples: lists/maps of scalars.
    lines=[ln.rstrip('\r') for ln in text.splitlines() if ln.strip() and not ln.lstrip().startswith('#')]
    if not lines: return []
    if lines[0].lstrip().startswith('-'):
        arr=[]; cur=None
        for ln in lines:
            stripped=ln.lstrip(); indent=len(ln)-len(stripped)
            if stripped.startswith('-'):
                if cur is not None: arr.append(cur)
                rest=stripped[1:].strip()
                if rest == "":
                    cur=OrderedDict()
                elif rest.startswith('{'):
                    cur=parse_inline_map(rest)
                elif ':' in rest:
                    cur=OrderedDict(); k,v=rest.split(':',1); cur[k.strip()]=parse_simple_scalar(v)
                else:
                    cur=parse_simple_scalar(rest)
            else:
                if isinstance(cur, dict) and ':' in stripped:
                    k,v=stripped.split(':',1); cur[k.strip()]=parse_simple_scalar(v)
        if cur is not None: arr.append(cur)
        return arr
    # root map, with support for key: followed by indented list of maps
    root=OrderedDict(); i=0
    while i < len(lines):
        ln=lines[i]
        if not ln.startswith(' ') and ':' in ln:
            k,v=ln.split(':',1); key=k.strip(); val=v.strip()
            if val:
                root[key]=parse_simple_scalar(val); i+=1
            else:
                # collect indented block
                block=[]; i+=1
                while i < len(lines) and (lines[i].startswith(' ') or lines[i].startswith('\t')):
                    block.append(lines[i][2:] if lines[i].startswith('  ') else lines[i].lstrip())
                    i+=1
                root[key]=parse_yaml_text('\n'.join(block))
        else:
            i+=1
    return root


def parse_yaml_rows(text, selector, opt):
    try:
        data = json.loads(text, object_pairs_hook=OrderedDict)
    except Exception:
        data = parse_yaml_text(text)
    jq = opt["ijq"] or selector
    if jq:
        data = apply_selector(data, jq)
    recs = json_records_from_data(data)
    if opt["is"]: recs = recs[max(0,opt["is"]):]
    if opt["ilr"]: recs = recs[:opt["ilr"]]
    cols=[]; seen=set()
    for rec in recs:
        if isinstance(rec, dict):
            for k in rec.keys():
                if k not in seen: seen.add(k); cols.append(k)
        else:
            if "c1" not in seen: seen.add("c1"); cols.append("c1")
    rows=[]
    for idx, rec in enumerate(recs,1):
        if isinstance(rec, dict):
            row=[convert_inull(scalar_to_text(rec.get(c), compact=False), opt) for c in cols]
        else:
            row=[convert_inull(scalar_to_text(rec, compact=False), opt)] + [None]*(len(cols)-1)
        if opt["inum"]: row=[str(idx)]+row
        rows.append(row)
    if opt["inum"]: cols=["num"]+cols
    return cols, ["TEXT"]*len(cols), rows


def split_tbln_bar(line):
    line=line.strip()
    if line.startswith('|'): line=line[1:]
    if line.endswith('|'): line=line[:-1]
    return [part.strip() for part in line.split('|')]


def parse_tbln_rows(text, opt):
    cols=None; types=None; data=[]
    for raw in text.splitlines():
        line=raw.strip()
        if not line: continue
        low=line.lower()
        if low.startswith('; name:'):
            after=line.split(':',1)[1]
            cols=split_tbln_bar(after)
        elif low.startswith('; type:'):
            after=line.split(':',1)[1]
            types=split_tbln_bar(after)
        elif line.startswith('|'):
            vals=split_tbln_bar(line)
            data.append(vals)
    if cols is None:
        preread=max(1,opt["ir"] or 1)
        width=0
        for r in data[:preread]: width=max(width,len(r))
        cols=[f"c{i}" for i in range(1,width+1)]
    if types is None: types=["text"]*len(cols)
    types=(types+["text"]*len(cols))[:len(cols)]
    if opt["is"]: data=data[max(0,opt["is"]):]
    if opt["ilr"]: data=data[:opt["ilr"]]
    rows=[]
    for idx,r in enumerate(data,1):
        row=[]
        for i,c in enumerate(cols):
            v = r[i] if i < len(r) else ""
            if v == "":
                val = None
            else:
                val = convert_inull(v, opt)
                typ=types[i].lower() if i < len(types) else "text"
                if val is not None and typ in ("int","integer"):
                    try: val=int(str(val))
                    except: pass
                elif val is not None and typ in ("float","real","numeric","number"):
                    try:
                        fv=float(str(val)); val = int(fv) if fv.is_integer() and '.' not in str(val) else fv
                    except: pass
            row.append(val)
        if opt["inum"]: row=[idx]+row
        rows.append(row)
    sqltypes=[]
    for t in types:
        tl=t.lower()
        if tl in ("int","integer"): sqltypes.append("INTEGER")
        elif tl in ("float","real","numeric","number"): sqltypes.append("NUMERIC")
        else: sqltypes.append("TEXT")
    if opt["inum"]:
        cols=["num"]+cols; sqltypes=["INTEGER"]+sqltypes
    return cols, sqltypes, rows


def parse_text_rows(text, opt):
    lines=text.splitlines()
    if opt["is"]: lines=lines[max(0,opt["is"]):]
    if opt["ilr"]: lines=lines[:opt["ilr"]]
    cols=["text"]
    rows=[]
    for idx,line in enumerate(lines,1):
        row=[convert_inull(line,opt)]
        if opt["inum"]: row=[str(idx)]+row
        rows.append(row)
    if opt["inum"]: cols=["num"]+cols
    return cols,["TEXT"]*len(cols),rows


def spans_from_width_header(line):
    spans=[]; in_span=False; start=0
    for i,ch in enumerate(line.rstrip('\r\n')):
        if ch != ' ' and not in_span:
            start=i; in_span=True
        if in_span and (ch == ' '):
            # end span at first space; consecutive spaces are separators
            spans.append((start,i)); in_span=False
    if in_span: spans.append((start,len(line.rstrip('\r\n'))))
    # Merge spans separated by a single space (words within a column); keep 2+ spaces separators.
    merged=[]
    for sp in spans:
        if merged and sp[0]-merged[-1][1] == 1:
            merged[-1]=(merged[-1][0], sp[1])
        else:
            merged.append(sp)
    return merged


def parse_width_rows(text,opt):
    lines=text.splitlines()
    if opt["is"]: lines=lines[max(0,opt["is"]):]
    if not lines: return [],[],[]
    header=lines[0]
    spans=spans_from_width_header(header)
    cols=[header[a:b].strip() or f"c{i}" for i,(a,b) in enumerate(spans,1)]
    rows=[]
    for idx,line in enumerate(lines[1:],1):
        vals=[]
        for a,b in spans:
            vals.append(convert_inull(line[a:b].strip() if a < len(line) else "", opt))
        if opt["inum"]: vals=[str(idx)]+vals
        rows.append(vals)
    if opt["ilr"]: rows=rows[:opt["ilr"]]
    if opt["inum"]: cols=["num"]+cols
    return cols,["TEXT"]*len(cols),rows


def quote_ident(s):
    return '"' + s.replace('"','""') + '"'


def looks_like_table_ref(content, opt):
    if content == "-": return True
    path = content.split("::",1)[0]
    if path == "-": return True
    # A real path is the best signal.
    if os.path.exists(path): return True
    lower=path.lower()
    known=(".csv",".tsv",".ltsv",".json",".jsonl",".ndjson",".yaml",".yml",".tbln")
    if lower.endswith(known) and ("/" in path or "\\" in path or opt["t"] or any(opt[f] for f in INPUT_FLAGS)):
        return True
    return False

class Engine:
    def __init__(self,opt):
        self.opt=opt
        if opt["dsn"] and (opt["driver"] in ("", "sqlite3", "sqlite3_ext")):
            self.con=sqlite3.connect(opt["dsn"])
        else:
            self.con=sqlite3.connect(":memory:")
        try:
            self.con.create_function("sqlite_version",0,lambda:"3.51.1")
        except Exception:
            pass
        self.cache={}
        self.counter=0
        self.stdin_cache=None
        self.schema_types={}  # result-column-name -> tbln-ish type
    def load_ref(self, spec):
        if spec in self.cache: return self.cache[spec]
        path, selector = (spec.split("::",1)+[""])[:2] if "::" in spec else (spec, "")
        if path == "-":
            if self.stdin_cache is None:
                self.stdin_cache=sys.stdin.read()
            text=self.stdin_cache
        else:
            try:
                text=read_text_file(path)
            except FileNotFoundError as e:
                raise TrdError(f"open {path}: no such file or directory", "ERROR")
            except Exception as e:
                raise TrdError(str(e), "ERROR")
        fmt=guess_format(path, self.opt)
        if fmt == "csv": cols, types, rows = parse_csv_rows(text, path, self.opt)
        elif fmt == "ltsv": cols, types, rows = parse_ltsv_rows(text, self.opt)
        elif fmt == "json": cols, types, rows = parse_json_rows(text, path, selector, self.opt)
        elif fmt == "yaml": cols, types, rows = parse_yaml_rows(text, selector, self.opt)
        elif fmt == "tbln": cols, types, rows = parse_tbln_rows(text, self.opt)
        elif fmt == "text": cols, types, rows = parse_text_rows(text, self.opt)
        elif fmt == "width": cols, types, rows = parse_width_rows(text, self.opt)
        else: cols, types, rows = parse_csv_rows(text, path, self.opt)
        unique_or_error(cols)
        tname=f"__trdsql_{self.counter}"
        self.counter += 1
        coldefs=[]
        for c,t in zip(cols,types):
            coldefs.append(f"{quote_ident(c)} {t}")
        self.con.execute(f"CREATE TABLE {quote_ident(tname)} ({', '.join(coldefs)})")
        if cols:
            ph=','.join(['?']*len(cols))
            sql=f"INSERT INTO {quote_ident(tname)} VALUES ({ph})"
            self.con.executemany(sql, rows)
        self.cache[spec]=tname
        for c,t in zip(cols,types):
            # Use source declared type for TBLN-ish output.
            if t.upper().startswith("INT"):
                self.schema_types[c]="int"
            elif t.upper().startswith(("NUM","REAL","FLOA","DOUB")):
                self.schema_types[c]="numeric"
            else:
                self.schema_types.setdefault(c,"text")
        return tname
    def rewrite_sql(self, sql):
        out=[]; i=0; n=len(sql)
        while i<n:
            ch=sql[i]
            if ch in ("'", '"', '`'):
                quote=ch; j=i+1; content=[]
                while j<n:
                    if sql[j]==quote:
                        # doubled quote escape for SQL strings/idents
                        if j+1<n and sql[j+1]==quote:
                            content.append(quote); j+=2; continue
                        break
                    content.append(sql[j]); j+=1
                if j<n and sql[j]==quote:
                    cont=''.join(content)
                    if quote in ('"','`') and looks_like_table_ref(cont, self.opt):
                        t=self.load_ref(cont)
                        out.append(quote_ident(tname_alias_safe(t)))
                    else:
                        out.append(sql[i:j+1])
                    i=j+1
                else:
                    out.append(ch); i+=1
            elif ch.isspace() or ch in ",();":
                out.append(ch); i+=1
            else:
                j=i
                while j<n and (not sql[j].isspace()) and sql[j] not in ",();":
                    j+=1
                tok=sql[i:j]
                # strip a trailing semicolon-like punctuation not handled above just in case
                if looks_like_table_ref(tok, self.opt):
                    t=self.load_ref(tok)
                    out.append(quote_ident(tname_alias_safe(t)))
                else:
                    out.append(tok)
                i=j
        return ''.join(out)

def tname_alias_safe(t):
    return t


def output_format(opt):
    # Fixed precedence chosen to match the common observed pair behavior.
    if opt["ovf"]: return "vf"
    if opt["omd"]: return "md"
    if opt["oat"]: return "at"
    if opt["oltsv"]: return "ltsv"
    if opt["ojsonl"]: return "jsonl"
    if opt["ojson"]: return "json"
    if opt["oyaml"]: return "yaml"
    if opt["otbln"]: return "tbln"
    if opt["oraw"]: return "raw"
    return "csv"


def guess_output_from_out(path):
    low=path.lower()
    # remove compression suffix first
    for suff in (".gz",".bz2",".xz",".zst",".zstd",".lz4"):
        if low.endswith(suff): low=low[:-len(suff)]
    if low.endswith(".jsonl") or low.endswith(".ndjson"): return "jsonl"
    if low.endswith(".json"): return "json"
    if low.endswith(".ltsv"): return "ltsv"
    if low.endswith(".tbln"): return "tbln"
    if low.endswith(".md") or low.endswith(".markdown"): return "md"
    if low.endswith(".yaml") or low.endswith(".yml"): return "yaml"
    if low.endswith(".tsv"): return "csv"
    return "csv"


def val_to_str(v, opt):
    if v is None:
        return opt["onull"] if opt.onull_set else ""
    if isinstance(v, float):
        return str(v)
    return str(v)


def csv_quote_field(s, delim, quotechar, quote_all=False):
    if quotechar == "":
        return s
    need = quote_all or (delim and delim in s) or (quotechar and quotechar in s) or ('\n' in s) or ('\r' in s) or (len(s)>0 and s[0]==' ')
    if not need:
        return s
    return quotechar + s.replace(quotechar, quotechar+quotechar) + quotechar


def format_csv(cols, rows, opt):
    delim=delimiter_from(opt["od"])
    q=opt["oq"]
    line_end="\r\n" if opt["ocrlf"] else "\n"
    lines=[]
    if opt["oh"]:
        lines.append(delim.join(csv_quote_field(str(c),delim,q,opt["oaq"]) for c in cols))
    for row in rows:
        fields=[csv_quote_field(val_to_str(v,opt),delim,q,opt["oaq"]) for v in row]
        lines.append(delim.join(fields))
    return line_end.join(lines) + (line_end if lines else "")


def format_raw(cols, rows, opt):
    delim=delimiter_from(opt["od"])
    line_end="\r\n" if opt["ocrlf"] else "\n"
    lines=[]
    if opt["oh"]:
        lines.append(delim.join(str(c) for c in cols))
    for row in rows:
        lines.append(delim.join(val_to_str(v,opt) for v in row))
    return line_end.join(lines) + (line_end if lines else "")


def parse_jsonish_string(s):
    if isinstance(s,str) and s and s[0] in "[{":
        try:
            return json.loads(s, object_pairs_hook=OrderedDict)
        except Exception:
            return s
    return s


def json_value(v,opt):
    if opt.onull_set and not isinstance(v,str):
        return opt["onull"]
    if v is None:
        return opt["onull"] if opt.onull_set else None
    if isinstance(v,(int,float)):
        return v
    if isinstance(v,str):
        return parse_jsonish_string(v)
    return v


def dumps_go_json(obj, pretty=False):
    if pretty:
        s=json.dumps(obj, ensure_ascii=False, indent=2)
    else:
        s=json.dumps(obj, ensure_ascii=False, separators=(",",":"))
    # Go's encoding/json escapes HTML characters by default.
    return s.replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')


def format_json(cols, rows, opt):
    arr=[]
    for row in rows:
        od=OrderedDict()
        for c,v in zip(cols,row): od[c]=json_value(v,opt)
        arr.append(od)
    return dumps_go_json(arr, pretty=True)+"\n"


def format_jsonl(cols, rows, opt):
    lines=[]
    for row in rows:
        od=OrderedDict()
        for c,v in zip(cols,row): od[c]=json_value(v,opt)
        lines.append(dumps_go_json(od, pretty=False))
    return "\n".join(lines) + ("\n" if lines else "")


def format_ltsv(cols, rows, opt):
    lines=[]
    for row in rows:
        lines.append("\t".join(f"{c}:{val_to_str(v,opt)}" for c,v in zip(cols,row)))
    return "\n".join(lines)+("\n" if lines else "")


def display_width(s):
    # Good enough for monospaced ASCII samples.
    return len(str(s))


def is_numeric_text(s):
    if s is None: return False
    if isinstance(s,(int,float)): return True
    st=str(s)
    return bool(re.match(r"^-?(?:\d+\.?\d*|\d*\.\d+)$", st))


def col_alignments(rows):
    if not rows: return []
    n=len(rows[0]) if rows else 0
    aligns=[]
    for i in range(n):
        vals=[r[i] for r in rows if i < len(r) and r[i] is not None and val_to_str(r[i], Options())!=""]
        aligns.append(bool(vals) and all(is_numeric_text(v) for v in vals))
    return aligns


def center_text(s,width):
    s=str(s); pad=width-len(s)
    left=pad//2; right=pad-left
    return " "*left+s+" "*right


def format_table(cols, rows, opt, markdown=False):
    str_rows=[[val_to_str(v,opt) for v in r] for r in rows]
    n=len(cols)
    widths=[]
    for i,c in enumerate(cols):
        w=len(str(c))
        for r in str_rows:
            if i < len(r): w=max(w,len(r[i]))
        widths.append(w)
    aligns=[]
    for i in range(n):
        vals=[r[i] for r in rows if i < len(r) and r[i] is not None and val_to_str(r[i],opt)!=""]
        aligns.append(bool(vals) and all(is_numeric_text(v) for v in vals))
    sep="|".join("-"*(w+2) for w in widths)
    border="+" + "+".join("-"*(w+2) for w in widths) + "+"
    header="|" + "|".join(" "+center_text(str(c),widths[i])+" " for i,c in enumerate(cols)) + "|"
    lines=[]
    if not markdown: lines.append(border)
    lines.append(header)
    lines.append("|" + sep + "|" if markdown else border)
    for r in str_rows:
        parts=[]
        for i,w in enumerate(widths):
            s=r[i] if i < len(r) else ""
            if aligns[i]:
                cell=s.rjust(w)
            else:
                cell=s.ljust(w)
            parts.append(" "+cell+" ")
        lines.append("|"+"|".join(parts)+"|")
    if not markdown: lines.append(border)
    return "\n".join(lines)+("\n" if lines else "")


def yaml_key(k):
    # yaml.v2 quotes keys like n/y that are YAML 1.1 booleans.
    low=str(k).lower()
    if low in {"y","yes","n","no","true","false","on","off","null","~"} or not re.match(r"^[A-Za-z_][A-Za-z0-9_ -]*$", str(k)):
        return '"'+str(k).replace('"','\\"')+'"'
    return str(k)


def yaml_scalar(v,opt):
    if opt.onull_set and not isinstance(v,str):
        return opt["onull"]
    if v is None:
        return opt["onull"] if opt.onull_set else "null"
    if isinstance(v,(int,float)):
        return str(v)
    if isinstance(v,str):
        if v == "": return "null"
        # yaml.v2 tends to emit plain scalars; trim leading/trailing whitespace in plain form.
        return v.strip()
    return str(v)


def yaml_emit_value(lines, prefix, key, value, opt):
    val=json_value(value,opt) if isinstance(value,str) else (opt["onull"] if opt.onull_set and value is not None and not isinstance(value,str) else value)
    k=yaml_key(key)
    if isinstance(val, list):
        lines.append(f"{prefix}{k}:")
        for item in val:
            if isinstance(item, dict):
                lines.append(f"{prefix}-")
                for kk,vv in item.items():
                    yaml_emit_value(lines, prefix+"  ", kk, vv, opt)
            else:
                lines.append(f"{prefix}- {yaml_scalar(item,opt)}")
    elif isinstance(val, dict):
        lines.append(f"{prefix}{k}:")
        for kk,vv in val.items():
            yaml_emit_value(lines, prefix+"  ", kk, vv, opt)
    else:
        lines.append(f"{prefix}{k}: {yaml_scalar(val,opt)}")


def format_yaml(cols, rows, opt):
    lines=[]
    for row in rows:
        if not cols:
            lines.append("- null"); continue
        # first key uses '- key: value'
        first=True
        for c,v in zip(cols,row):
            val=json_value(v,opt) if isinstance(v,str) else v
            k=yaml_key(c)
            if first:
                if isinstance(val,(list,dict)):
                    lines.append(f"- {k}:")
                    if isinstance(val,list):
                        for item in val: lines.append(f"  - {yaml_scalar(item,opt)}")
                    else:
                        for kk,vv in val.items(): yaml_emit_value(lines,"  ",kk,vv,opt)
                else:
                    lines.append(f"- {k}: {yaml_scalar(v,opt)}")
                first=False
            else:
                val2=json_value(v,opt) if isinstance(v,str) else v
                if isinstance(val2,(list,dict)):
                    yaml_emit_value(lines,"  ",c,v,opt)
                else:
                    lines.append(f"  {k}: {yaml_scalar(v,opt)}")
    return "\n".join(lines)+("\n" if lines else "")


def format_vf(cols, rows, opt):
    namew=max([len(str(c)) for c in cols]+[0])+2
    lines=[]
    for idx,row in enumerate(rows,1):
        lines.append(f"---[ {idx}]" + "-"*24)
        for c,v in zip(cols,row):
            lines.append(f"{str(c).rjust(namew)} | {val_to_str(v,opt)}")
    return "\n".join(lines)+("\n" if lines else "")


def format_tbln(cols, rows, opt, schema_types):
    types=[]
    for c in cols:
        types.append(schema_types.get(c,"text"))
    lines=[]
    lines.append("; name: | " + " | ".join(str(c) for c in cols) + " |")
    lines.append("; type: | " + " | ".join(types) + " |")
    for r in rows:
        lines.append("| " + " | ".join(val_to_str(v,opt) for v in r) + " |")
    return "\n".join(lines)+"\n"


def fetch_query(engine, sql):
    rewritten=engine.rewrite_sql(sql)
    cur=engine.con.execute(rewritten)
    cols=[d[0] for d in cur.description] if cur.description else []
    rows=cur.fetchall() if cur.description else []
    return cols, rows, rewritten


def format_output(fmt, cols, rows, opt, schema_types):
    if fmt == "csv": return format_csv(cols, rows, opt)
    if fmt == "raw": return format_raw(cols, rows, opt)
    if fmt == "json": return format_json(cols, rows, opt)
    if fmt == "jsonl": return format_jsonl(cols, rows, opt)
    if fmt == "ltsv": return format_ltsv(cols, rows, opt)
    if fmt == "md": return format_table(cols, rows, opt, markdown=True)
    if fmt == "at": return format_table(cols, rows, opt, markdown=False)
    if fmt == "vf": return format_vf(cols, rows, opt)
    if fmt == "tbln": return format_tbln(cols, rows, opt, schema_types)
    if fmt == "yaml": return format_yaml(cols, rows, opt)
    return format_csv(cols, rows, opt)


def open_output(path, opt):
    if not path:
        return sys.stdout, False
    oz=opt["oz"].lower()
    if not oz:
        low=path.lower()
        if low.endswith(".gz"): oz="gz"
        elif low.endswith(".bz2"): oz="bz2"
        elif low.endswith(".xz"): oz="xz"
    if oz == "gz": return gzip.open(path,"wt",encoding="utf-8",newline=""), True
    if oz == "bz2": return bz2.open(path,"wt",encoding="utf-8",newline=""), True
    if oz == "xz": return lzma.open(path,"wt",encoding="utf-8",newline=""), True
    return open(path,"w",encoding="utf-8",newline=""), True


def analyze_file(path,opt, only_examples=False):
    eng=Engine(opt)
    try:
        t=eng.load_ref(path)
        # Use cached parse metadata by querying a single row.
        cols=list(eng.con.execute(f"PRAGMA table_info({quote_ident(t)})"))
        colnames=[c[1] for c in cols]
        rows=eng.con.execute(f"SELECT * FROM {quote_ident(t)} LIMIT 1").fetchall()
    except TrdError as e:
        raise
    fmt=guess_format(path,opt).upper()
    cmd="./executable"
    prefix_flags=[]
    if opt["ih"]: prefix_flags.append("-ih")
    pf=(" "+" ".join(prefix_flags)) if prefix_flags else ""
    select_cols=", ".join(colnames)
    where_col=colnames[0] if colnames else "c1"
    sample=val_to_str(rows[0][0],opt) if rows and rows[0] else ""
    examples=[
        f'{cmd}{pf} "SELECT {select_cols} FROM {path}"',
        f'{cmd}{pf} "SELECT {select_cols} FROM {path} WHERE {where_col} = \'{sample}\'"',
        f'{cmd}{pf} "SELECT {where_col}, count({where_col}) FROM {path} GROUP BY {where_col}"',
        f'{cmd}{pf} "SELECT {select_cols} FROM {path} ORDER BY {where_col} LIMIT 10"',
    ]
    if only_examples:
        return "\n".join(examples)+"\n"
    out=[]
    out.append(f"The table name is {path}.")
    out.append(f"The file type is {fmt}.")
    out.append("")
    out.append("Data types:")
    type_rows=[[c,"text"] for c in colnames]
    out.append(format_table(["column name","type"], type_rows, opt, markdown=False).rstrip("\n"))
    out.append("")
    out.append("Data samples:")
    out.append(format_table(colnames, rows, opt, markdown=False).rstrip("\n"))
    out.append("")
    out.append("Examples:")
    out.extend(examples)
    return "\n".join(out)+"\n"


def main(argv):
    opt=parse_args(argv)
    if opt["help"] or len(argv)==0:
        sys.stderr.write(HELP_TEXT)
        return 2
    if opt["version"]:
        sys.stdout.write("trdsql version devel\n")
        return 0
    if opt["dblist"]:
        return 0
    try:
        if opt["a"]:
            sys.stdout.write(analyze_file(opt["a"],opt,False)); return 0
        if opt["A"]:
            sys.stdout.write(analyze_file(opt["A"],opt,True)); return 0
    except TrdError as e:
        if e.prefix == "ERROR": sys.stderr.write(f"{nowstamp()} ERROR: {e.msg}\n")
        else: log_error(e.prefix,e.msg)
        return 1
    # Query source
    if opt["q"]:
        try:
            query=read_text_file(opt["q"])
        except FileNotFoundError:
            sys.stderr.write(f"{nowstamp()} ERROR: open {opt['q']}: no such file or directory\n")
            return 1
    elif opt["t"]:
        # Conversion mode: ignore positional SQL and select all from the named table.
        tref=opt["t"]
        if any(ch.isspace() for ch in tref) or tref == "-":
            query=f"SELECT * FROM `{tref}`"
        else:
            query=f"SELECT * FROM {tref}"
    else:
        query=" ".join(opt.args)
    if not query:
        sys.stderr.write(HELP_TEXT)
        return 2
    eng=Engine(opt)
    try:
        cols, rows, rewritten=fetch_query(eng, query)
    except TrdError as e:
        if e.prefix == "ERROR":
            sys.stderr.write(f"{nowstamp()} ERROR: {e.msg}\n")
        else:
            log_error(e.prefix, e.msg, query.strip())
        return 1
    except sqlite3.Error as e:
        log_error("export", str(e), query.strip())
        return 1
    fmt=output_format(opt)
    if opt["out"] and not opt.explicit_output and not opt["out-without-guess"]:
        fmt=guess_output_from_out(opt["out"])
        # .tsv output is CSV with tab delimiter in the real tool; emulate lightly.
        if opt["out"].lower().endswith(".tsv") and opt["od"] == ",":
            opt["od"]="\t"
    data=format_output(fmt, cols, rows, opt, eng.schema_types)
    try:
        f,close=open_output(opt["out"],opt)
        f.write(data)
        if close: f.close()
    except Exception as e:
        sys.stderr.write(f"{nowstamp()} ERROR: {e}\n")
        return 1
    return 0

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
